{
  "probability": 0.96,
  "range_low": 0.88,
  "range_high": 0.98,
  "summary": [
    "February 2026 IOM data show 606 Mediterranean deaths, making 900 by end-March plausible but not certain.",
    "March pace, weather, policy deterrence, and SAR capacity are key drivers that tilt the odds upward while leaving notable uncertainty.",
    "Calibrated to a high posterior, the estimate reflects strong upward pressure with some potential revisions to counts."
  ],
  "confidence": "high",
  "narrative": "Starting from the Central Mediterranean reference class and updating on March pace, weather risks, deterrence effects, and SAR capacity, the posterior probability of reaching at least 900 deaths before April 2026 is 96%. While February data signal high risk, the outcome remains contingent on March conditions and data revisions, justifying a high but not absolute confidence range.",
  "justification": {
    "anchor": {
      "probability": 0.70,
      "basis": "reference class is Central Mediterranean fatalities; anchor chosen based on IOM reporting of 606 deaths by end-February 2026 and the observed early-year intensity, which support a non-negligible baseline risk of reaching 900 by end-March."
    },
    "factor_updates": [
      {
        "factor": "March 2026 toll pace required to reach 900",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "With 606 deaths by February, about 294 more would be needed in March; given February’s pace and potential continuation, the probability mass shifts upward substantially."
      },
      {
        "factor": "Weather-related storms driving higher fatalities",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Adverse sea conditions can elevate fatalities; early 2026 data show impactful weather risks that could persist into March."
      },
      {
        "factor": "Policy crackdown and reduced safe passage increasing risk-taking",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Stricter deterrence can push crossings toward more dangerous routes, elevating mortality risk."
      },
      {
        "factor": "SAR capacity and funding constraints increasing fatalities",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Limited rescue capacity correlates with higher mortality on irregular crossings."
      },
      {
        "factor": "Data reporting lags and missing victims creating uncertainty",
        "direction": "neutral",
        "magnitude": "weak",
        "rationale": "Ongoing revisions could slightly move totals up or down, but current signals favor a continued high pace rather than a clear downward trend."
      }
    ],
    "synthesis_rationale": "Starting from a 0.70 anchor based on the February total and well-established high-risk context, the combination of a strong March-pace requirement and multiple upward-moving factors yields a posterior around 0.96. While data revisions and March variability introduce uncertainty, the overall calibration leans toward a high likelihood of reaching 900 deaths before April, justifying a narrow high-probability range."
  }
}

{
  "probability": 0.96,
  "range_low": 0.88,
  "range_high": 0.99,
  "summary": [
    "606 deaths by February 2026 on the Central Mediterranean route; ongoing March pace could push toll above 900 before April if March remains high.",
    "Upward drivers include pace through February, seasonality and weather risk, policy deterrence potentially increasing risk-taking, and reporting revisions that could lift totals.",
    "Uncertainty remains due to SAR capacity, weather variability, and data revisions that could alter the pace; downward shifts are possible if SAR capacity improves or deterrence reduces crossing risk.",
    "Overall, the calibrated probability is high, with a plausible 0.88–0.99 range around the posterior."
  ],
  "confidence": "high",
  "narrative": "Given 606 deaths through February 2026 and high March-risk conditions, reaching 900 deaths before April is very likely, though not guaranteed due to weather, SAR capacity, and data revisions that could alter the pace.",
  "justification": {
    "anchor": {
      "probability": 0.70,
      "basis": "Reference class anchored on IOM Missing Migrants Project tallies for 2026 on the Central Mediterranean; the February count of around 606 provides a concrete starting point for projecting March outcomes."
    },
    "factor_updates": [
      {
        "factor": "Current pace Jan-Feb 2026",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "606 deaths by February; sustaining this pace through March makes 900 by end-March plausible."
      },
      {
        "factor": "March weather and SAR conditions",
        "direction": "neutral",
        "magnitude": "weak",
        "rationale": "Weather variability could either raise or lower March fatalities; this factor introduces uncertainty."
      },
      {
        "factor": "Policy deterrence effects on crossing risk",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Tighter controls may push migrants toward more dangerous crossings, increasing fatalities."
      },
      {
        "factor": "Data reporting/revision uncertainty",
        "direction": "neutral",
        "magnitude": "weak",
        "rationale": "IOM counts can be revised; upward revisions could push totals above 900 even if March is not extremely deadly."
      },
      {
        "factor": "Seasonality/early-year peak in Central Mediterranean",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Early-year spike supports higher totals; combined with February baseline enhances probability of reaching 900."
      }
    ],
    "synthesis_rationale": "Starting from a February baseline of 606, multiple upward pressures (pace, seasonality, policy-driven risk-taking) combine with uncertain March outcomes; given potential revisions, the posterior 0.96 reflects high confidence in surpassing 900 before April, but correlated factors and potential downward shifts keep residual uncertainty. The range accounts for that calibration, but the posterior value should reflect the stated 96%."
  }
}

{
  "probability": 0.40,
  "range_low": 0.25,
  "range_high": 0.60,
  "summary": [
    "606 Mediterranean deaths had been recorded by February 2026; reaching 900 by end-March requires roughly 294 additional deaths in March, a plausible but uncertain pace.",
    "March weather and SAR conditions, along with policy/deterrence effects, introduce both upside and downside risks to mortality totals.",
    "Data reporting revisions and lags add further uncertainty, making the 900-by-end-March target non-guaranteed yet within the realm of possibility."
  ],
  "confidence": "low",
  "narrative": "Starting from a lower-end anchor based on 606 deaths by February 2026, the March toll would need about 294 deaths to hit 900. While ongoing peril in the Central Mediterranean persists, countervailing factors—improved SAR, deterrence effects, and reporting revisions—inject substantial uncertainty; the target is plausible but not the most likely outcome.",
  "justification": {
    "anchor": {
      "probability": 0.28,
      "basis": "Lower-end anchor derived from Jan–Feb 2026 counts on the Central Mediterranean (e.g., 375 in January, 606 by February), projecting a modest probability (~28%) of reaching 900 by end-March if March sustains a similar pace."
    },
    "factor_updates": [
      {
        "factor": "Current pace of Mediterranean fatalities in Jan-Feb 2026",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "606 deaths by February imply a high January–February pace; to reach 900 by end-March would require March to deliver around 294 deaths, which is plausible but not guaranteed."
      },
      {
        "factor": "March weather and SAR conditions",
        "direction": "neutral",
        "magnitude": "weak",
        "rationale": "March conditions are variable; extreme seas could raise deaths, while calmer seas or expanded SAR capacity could suppress fatalities."
      },
      {
        "factor": "European policy/deterrence measures affecting crossing risk",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Tighter controls may push migrants toward riskier crossings, potentially increasing fatalities, though effects may be offset by enforcement and routing changes."
      },
      {
        "factor": "Data reporting/revision uncertainty (IOM counts)",
        "direction": "neutral",
        "magnitude": "weak",
        "rationale": "Counts can be revised upward or downward; early-year tallies may underestimate or overestimate true totals as information solidifies."
      },
      {
        "factor": "Seasonality/early-year peak in the Central Mediterranean",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Early-year intensity has historically high fatality potential; if this persists, March could push totals higher toward 900."
      },
      {
        "factor": "March 2026 toll pace required to reach 900",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "To reach 900 by end-March, March would need approximately 294 deaths; given February's pace, this is possible but hinges on continued high March fatalities."
      }
    ],
    "synthesis_rationale": "Starting from a conservative anchor (0.28) anchored to February counts, the factor updates tilt both up and down but collectively favor only a moderate probability of reaching 900 by end-March. The synthesis accounts for high downside risk from policy and SAR improvements and data revisions, but the persistent high pace seen in Jan–Feb keeps the upper bound non-negligible; calibration favors a cautious, low-to-mid probability with wide uncertainty."
  }
}
